procedure ClinicAppointmentReminders {
  about "Remind each patient about their appointment"
  policy ClinicPolicy
  sheet Visits "Visits" { patient: Text, phone: Phone, starts: DateTime, status: Text, copay: Money, diagnosis: Text private }
  trigger every day at 10:00

  let all = fetch Visits
  let due = filter all where date_of(starts) == today() + 2 days and status == "booked"
  for each r in due up to 20 {
    let m = draft sms to r.phone: "Hi {r.patient}, a reminder from the clinic: your appointment is in two days at {time_of(r.starts)}."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
  }
}

procedure ClinicAppointmentReminders {
  about "Remind each patient about their appointment"
  policy ClinicPolicy
  sheet Visits "Visits" { patient: Text, phone: Phone, starts: DateTime, status: Text, copay: Money, diagnosis: Text private }
  trigger every thursday at 11:00

  let all = fetch Visits
  let due = filter all where date_of(starts) == today() + 1 day and status == "booked"
  for each r in due up to 20 {
    let m = draft sms to r.phone: "Hi {r.patient}, a reminder from the clinic: your appointment is tomorrow at {time_of(r.starts)}."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
  }
}

procedure ClinicNoShowFollowUp {
  about "Follow up with patients marked no-show"
  policy ClinicPolicy
  sheet Visits "Visits" { patient: Text, phone: Phone, starts: DateTime, status: Text, copay: Money, diagnosis: Text private }
  trigger every day at 11:00

  let all = fetch Visits
  let recent = filter all where status == "no-show" and days_between(starts, today()) <= 2 and days_between(starts, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no no-show patients"
  }
  notify owner "No-show patients to follow up: {n}"
  for each r in recent up to 20 {
    let m = draft sms to r.phone: "Hi {r.patient}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
    update r set status = "followed-up"
  }
}

procedure ClinicWinBack {
  about "Nudge patients whose appointment was long ago"
  policy ClinicPolicy
  sheet Visits "Visits" { patient: Text, phone: Phone, starts: DateTime, status: Text, copay: Money, diagnosis: Text private }
  trigger every thursday at 08:00

  let all = fetch Visits
  let old = filter all where days_between(starts, today()) >= 30 and status != "cancelled"
  let oldest = sort old by starts first 10
  for each r in oldest up to 10 {
    let m = draft sms to r.phone: "Hi {r.patient default 'there'}, it's been a while! We'd love to see you again at the clinic."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
  }
}

procedure ClinicConfirmNewAppointment {
  about "Confirm a new appointment and add it to the calendar"
  policy ClinicPolicy
  sheet Visits "Visits" { patient: Text, phone: Phone, starts: DateTime, status: Text, copay: Money, diagnosis: Text private }
  calendar Rooms "Rooms"
  trigger when new row r in Visits

  if r.starts < now() + 24 hours {
    notify owner "Short-notice appointment for {r.patient} at {r.starts}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft sms to r.phone: "Hi {r.patient default 'there'}, your appointment with the clinic is confirmed for {r.starts}."
  let ok = request approval of m from owner timeout 2 hours else stop "confirmation not approved"
  send ok
  let ev = book Rooms { title: "{r.patient}", at: r.starts, length: 30 minutes }
  update r set status = "confirmed"
}

procedure ClinicConfirmNewAppointment {
