procedure ClinicOutreachCampaign {
  about "On request, contact recent cancelled patients"
  policy ClinicPolicy
  sheet Visits "Visits" { patient: Text, phone: Phone, starts: DateTime, status: Text, copay: Money, diagnosis: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Visits
  let targets = filter all where status == "cancelled" and days_between(starts, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft sms to r.phone: "Hi {r.patient default 'there'}, come back to the clinic! Use code COMEBACK15 on your next visit."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

