policy:
policy AutorepairStockPolicy {
  allow read Parts(part, count, minimum, reorder_qty, supplier, unit_price)
  allow supplier Parts.supplier
  limit order $100 per action
  limit order $500 per day
}

program:
procedure AutorepairReorder {
  about "Reorder parts below their minimum"
  policy AutorepairStockPolicy
  sheet Parts "Parts" { part: Text, count: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_price: Money }
  trigger every day at 08:30

  let all = fetch Parts
  let low = filter all where count < minimum
  for each i in low up to 5 {
    let cost = i.reorder_qty * i.unit_price
    if cost > $100.00 {
      notify owner "Reorder of {i.part} would cost {cost}, over the $100 limit."
      skip
    }
    order "{i.reorder_qty} x {i.part}" from i.supplier cost cost, ask owner first timeout 1 day else skip
    log "ordered {i.part}"
  }
}

procedure AutorepairRefunds {
  about "Handle refund requests within limits"
  policy AutorepairRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, owner_name: Text, phone: Phone, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 14 {
    notify owner "Refund request {r.request_id} is older than 14 days."
    stop "outside refund window"
  }
  if r.amount > $40.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $40. Please review."
    stop "over refund limit"
  }
  if r.amount <= $10.00 {
    refund r.amount for r.request_id reason "refund request"
  } else {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 12 hours else stop "refund not approved"
  }
  update r set status = "refunded"
  let m = draft sms to r.phone: "Hi {r.owner_name default 'there'}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 12 hours else stop "message not approved"
  send ok
}

procedure AutorepairConfirmNewPickupTime {
  about "Confirm a new pickup time and add it to the calendar"
  policy AutorepairPolicy
  sheet Jobs "Jobs" { owner_name: Text, phone: Phone, promised: DateTime, status: Text, estimate: Money, vin: Text private }
  calendar Bays "Bays"
  trigger when new row r in Jobs

  if r.promised < now() + 2 hours {
    notify owner "Short-notice pickup time for {r.owner_name} at {r.promised}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft sms to r.phone: "Hi {r.owner_name default 'there'}, your pickup time with the shop is confirmed for {r.promised}."
  let ok = request approval of m from owner timeout 2 hours else stop "confirmation not approved"
  send ok
  let ev = book Bays { title: "{r.owner_name}", at: r.promised, length: 90 minutes }
  update r set status = "confirmed"
}

