    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
  }
}

procedure PrintshopPrintJobReminders {
  about "Remind each customer about their print job"
  policy PrintshopPolicy
  sheet Jobs "Jobs" { customer: Text, email: Email, due: Date, status: Text, quote: Money, file_link: Text private }
  trigger every day at 10:00

  let all = fetch Jobs
  let due = filter all where due == today() + 3 days and status == "queued"
  let msgs = draft each r in due up to 20 email to r.email subject "Your print job in three days": "Hi {r.customer default 'there'}, a reminder from the shop: your print job is in three days."
  let ok = request batch approval of msgs from owner timeout 12 hours else stop "batch not approved"
  send ok
  for each r in due up to 20 {
    update r set status = "notified"
  }
}

procedure PrintshopWinBack {
  about "Nudge customers whose print job was long ago"
  policy PrintshopPolicy
  sheet Jobs "Jobs" { customer: Text, email: Email, due: Date, status: Text, quote: Money, file_link: Text private }
  trigger every day at 11:00

  let all = fetch Jobs
  let old = filter all where days_between(due, today()) >= 90 and status != "cancelled"
  let oldest = sort old by due first 20
  for each r in oldest up to 20 {
    let m = draft email to r.email subject "We miss you": "Hi {r.customer default 'there'}, it's been a while! We'd love to see you again at the shop."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

procedure PrintshopDailySummary {
  about "Tell the owner how many customers are queued"
  policy PrintshopPolicy
  sheet Jobs "Jobs" { customer: Text, email: Email, due: Date, status: Text, quote: Money, file_link: Text private }
  trigger every thursday at 08:30

  let all = fetch Jobs
  let these = filter all where status == "queued"
  let n = summarize count of these
  let total = summarize sum quote of these
  if n == 0 {
    stop "no queued customers"
  }
  notify owner "Queued customers: {n}, total quote: {total}"
}

procedure PrintshopRefunds {
  about "Handle refund requests within limits"
  policy PrintshopRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, customer: Text, email: Email, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 30 {
    notify owner "Refund request {r.request_id} is older than 30 days."
    stop "outside refund window"
  }
  if r.amount > $75.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $75. Please review."
    stop "over refund limit"
  }
  if r.amount <= $10.00 {
    refund r.amount for r.request_id reason "refund request"
  } else {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 12 hours else stop "refund not approved"
  }
  update r set status = "refunded"
  let m = draft email to r.email subject "Your refund": "Hi {r.customer default 'there'}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 12 hours else stop "message not approved"
  send ok
}

procedure PrintshopOutreachCampaign {
  about "On request, contact recent cancelled customers"
  policy PrintshopPolicy
  sheet Jobs "Jobs" { customer: Text, email: Email, due: Date, status: Text, quote: Money, file_link: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Jobs
  let targets = filter all where status == "cancelled" and days_between(due, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  let msgs = draft each r in targets up to 100 email to r.email subject "We'd love to see you": "Hi {r.customer}, come back to the shop! Use code WELCOME10 on your next visit."
  let ok = request batch approval of msgs from owner timeout 12 hours else stop "batch not approved"
  send ok
}
